const Row = memo(function Row({ item, columns, onPin }: RowProps) {
  return <tr>{columns.map((c) => <Cell key={c.key} value={item[c.key]} onPin={onPin} />)}</tr>;
});

function Table({ items }: { items: Item[] }) {
  const [pinned, setPinned] = useState<string[]>([]);

  const columns = useMemo(() => buildColumns(), [items]);
  const onPin = (id: string) => setPinned((p) => [...p, id]);

  const total = useMemo(() => items.length, [items]);

  return (
    <table>
      <caption>{total} rows</caption>
      <tbody>
        {items.map((it) => (
          <Row key={it.id} item={it} columns={columns} onPin={onPin} />
        ))}
      </tbody>
    </table>
  );
}

